package cl.skinspad.ticket.soporte;
import java.util.*;import java.time.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import static cl.skinspad.ticket.soporte.EstadosSoporte.*;import static cl.skinspad.ticket.soporte.SoporteDtos.*;import static cl.skinspad.ticket.soporte.SoporteIdentidad.*;
@Service @RequiredArgsConstructor public class TicketService {
 private final TicketRepository tickets;private final TicketMensajeRepository mensajes;private final SoporteCuotas cuotas;private final SoporteArchivos archivos;private final SoporteRegistro registro;private final SoporteContexto contexto;
 public Ticket acceso(Long id,Actor a){var t=tickets.findById(id).orElseThrow(()->new jakarta.persistence.EntityNotFoundException("Ticket no encontrado"));propietario(t.getUsuarioId(),a);return t;}
 private Ticket lock(Long id,Actor a){var t=tickets.bloquear(id).orElseThrow(()->new jakarta.persistence.EntityNotFoundException("Ticket no encontrado"));propietario(t.getUsuarioId(),a);return t;}
 public List<TicketVista> mios(Actor a){return tickets.findByUsuarioIdOrderByFechaCreacionDesc(a.id()).stream().map(t->vista(t,a,false)).toList();}
 public TicketVista obtener(Long id,Actor a){return vista(acceso(id,a),a,true);}
 private TicketVista vista(Ticket t,Actor a,boolean detalle){return new TicketVista(t.getId(),t.getVersion(),t.getAsunto(),t.getCategoria(),a.admin()?t.getEstado().name():simple(t.getEstado()),a.admin()?t.getPrioridad():null,a.admin()?t.getAdminAsignadoId():null,t.getOperacionId(),t.getArmaId(),t.getFechaCreacion(),t.getFechaActualizacion(),detalle?mensajes.findByTicket_IdOrderById(t.getId()).stream().map(m->new MensajeVista(m.getId(),a.admin()?m.getAutorId():"admin".equals(m.getRolAutor())?"Soporte":"Tú",m.getRolAutor(),m.getContenido(),m.getFecha())).toList():List.of(),detalle?archivos.listar("TICKET",t.getId()):List.of(),a.admin()&&detalle?registro.historial("TICKET",t.getId()):List.of());}
 @Transactional public TicketVista crear(NuevoTicket r,Actor a){cliente(a);if(r.categoria()==null)throw new IllegalArgumentException("Categoría obligatoria");contexto.referencias(r.operacionId(),r.armaId(),a);cuotas.consumir(a.id());var t=new Ticket();t.setUsuarioId(a.id());t.setAsunto(ValidacionSoporte.texto(r.asunto(),160));t.setCategoria(r.categoria());t.setOperacionId(r.operacionId());t.setArmaId(r.armaId());tickets.saveAndFlush(t);mensaje(t,new Mensaje(r.contenido(),r.adjuntos()),a,false);registro.evento("TICKET",t.getId(),a.id(),"CREAR",null,t.getEstado(),"Ticket creado");registro.avisar("T-"+t.getId()+"-CREAR","ADMIN","Nuevo ticket de soporte","/admin/soporte/tickets/"+t.getId());return vista(t,a,true);}
 private void mensaje(Ticket t,Mensaje r,Actor a,boolean notificar){var m=new TicketMensaje();m.setTicket(t);m.setAutorId(a.id());m.setRolAutor(a.admin()?"admin":"cliente");m.setContenido(ValidacionSoporte.texto(r.contenido(),4000));mensajes.saveAndFlush(m);archivos.guardar("TICKET",t.getId(),m.getId(),r.adjuntos());t.setFechaActualizacion(Instant.now());registro.evento("TICKET",t.getId(),a.id(),"MENSAJE",null,m.getId(),"Mensaje añadido");if(notificar)registro.avisar("TM-"+m.getId(),a.admin()?t.getUsuarioId():"ADMIN",a.admin()?"Soporte respondió a tu ticket":"Nuevo mensaje en ticket",(a.admin()?"/cliente/soporte/tickets/":"/admin/soporte/tickets/")+t.getId());}
 @Transactional public TicketVista responder(Long id,Mensaje r,Actor a){var t=lock(id,a);if(!abierto(t.getEstado()))throw new IllegalStateException("El ticket está finalizado; crea uno nuevo si necesitas ayuda adicional");mensaje(t,r,a,true);tickets.flush();return vista(t,a,true);}
 @Transactional public TicketVista cambiar(Long id,Cambio r,Actor a){var t=lock(id,a);ValidacionSoporte.version(r.version(),t.getVersion());String m=ValidacionSoporte.texto(r.motivo(),1000);if(!a.admin()&&(r.estado()!=Estado.CERRADO||r.prioridad()!=null))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN);
  if(r.estado()!=null&&r.estado()!=t.getEstado()){transicion(t.getEstado(),r.estado(),true,a.admin());registro.evento("TICKET",id,a.id(),"ESTADO",t.getEstado(),r.estado(),m);t.setEstado(r.estado());if(!abierto(r.estado())&&t.getFechaCierre()==null)t.setFechaCierre(Instant.now());}
  if(r.prioridad()!=null&&r.prioridad()!=t.getPrioridad()){registro.evento("TICKET",id,a.id(),"PRIORIDAD",t.getPrioridad(),r.prioridad(),m);t.setPrioridad(r.prioridad());}t.setFechaActualizacion(Instant.now());tickets.flush();registro.avisar("T-"+id+"-V"+t.getVersion(),a.admin()?t.getUsuarioId():"ADMIN","Se actualizó el estado de un ticket",(a.admin()?"/cliente/soporte/tickets/":"/admin/soporte/tickets/")+id);return vista(t,a,true);}
 @Transactional public TicketVista asignar(Long id,Asignacion r,Actor a){if(!a.admin())throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN);var t=lock(id,a);ValidacionSoporte.version(r.version(),t.getVersion());contexto.adminAsignable(r.adminId());String m=ValidacionSoporte.texto(r.motivo(),1000);if(!Objects.equals(t.getAdminAsignadoId(),r.adminId())){registro.evento("TICKET",id,a.id(),"ASIGNAR",t.getAdminAsignadoId(),r.adminId(),m);t.setAdminAsignadoId(r.adminId());t.setFechaActualizacion(Instant.now());tickets.flush();registro.avisar("T-ASIG-"+id+"-"+t.getVersion(),"ADMIN","Asignación de ticket actualizada","/admin/soporte/tickets/"+id);}return vista(t,a,true);}
}
